# Code generated by Claude
"""Live viewer window of the combined controller, built on the graphics library framework (GLFW) and MuJoCo.

The viewer was moved here from experiments/combined_controller.py. It owns the window, the third-person camera that
follows the robot base, the head-up display (HUD, the status panel and key legend drawn over the scene), the camera
insets along the bottom edge, snapshots, recording of the viewer to a video, key polling and frame pacing. The viewer
is a plain dictionary of callables, created by the launcher and passed to control_loop.run_loop():

    viewer = make_glfw_viewer(model, data, vcfg)
    viewer["frame"](info)

The keys of that dictionary are listed in the Returns section of make_glfw_viewer(). The module also provides
ViewerRecorder (video and comma-separated values (CSV) recording). The layout itself (the follow camera, the status panel,
the banner and the camera tiles) is in src/viewer_layout.py, shared with the offscreen renderer in src/viewer_composite.py;
this module only places those bitmaps with OpenGL.

The loop calls the viewer on every tick but asks for a redraw only every few ticks (its setting viewer_draw_hz is
30 Hz, which is every 5th tick of the 150 Hz tick); on the other ticks the viewer only polls
the keys and paces.

When vertical synchronisation (vsync) is off, each tick is held to the loop's tick period, so simulated time equals
wall-clock time whenever the machine keeps up.
"""

import csv
import time
import time as _time
from pathlib import Path

import cv2
import glfw
import mujoco
import numpy as np

from src import robot_specs
from src.alert_sound import play_alert
from src.viewer_layout import (FOVY_DEG, banner_bitmap, hud_bitmap, hud_key_list, hud_position, hud_rows, inset_layout, inset_tile,
                               setup_follow_camera, update_follow_camera)

PROJECT_ROOT = Path(__file__).resolve().parent.parent
CAMERA_SNAPSHOT_DIR = "data/camera_snapshots"


class ViewerRecorder:
    """Records the viewer image to an MP4 video and writes a CSV row per video frame.

    One CSV row is written for every video frame (column `video_frame` is the
    frame index), as the recording goes, and flushed every 30 rows, so the
    joint trajectory can be compared across frames and survives a crash. The
    MP4 plays at `fps` = video frames per second of simulated time (the
    loop's tick rate divided by the number of ticks per redraw, set by
    make_glfw_viewer's frame() when a recording starts), so playback runs at
    real simulated speed however slowly the viewer ran on the virtual machine.

    Attributes:
        directory (pathlib.Path): Folder that receives the video and the CSV
            file. Created by start() if it does not exist.
        fps (float): Video frames per second of simulated time.
        columns (list[str]): CSV column names after the leading `video_frame`
            column.
        writer (cv2.VideoWriter | None): Open video writer, or None when no
            recording is active.
        csv_file (file | None): Open CSV file, or None when no recording is
            active.
        csv (csv.writer | None): Writer on `csv_file`, or None when no
            recording is active.
        frames (int): Number of video frames written so far in the current
            recording.
        size (tuple[int, int] | None): Video frame size (width, height) in
            pixels, rounded down to even numbers. None before the first
            start().
        paths (tuple[pathlib.Path, pathlib.Path] | None): Paths of the MP4 and
            the CSV file of the current or last recording. None before the
            first start().
    """

    def __init__(self, directory, fps, columns):
        """Create an idle recorder; nothing is written until start() is called.

        Args:
            directory (str | pathlib.Path): Folder for the output files.
            fps (float): Video frames per second of simulated time.
            columns (list[str]): CSV column names that follow the leading
                `video_frame` column.
        """
        self.directory = Path(directory)
        self.fps = float(fps)
        self.columns = list(columns)
        self.writer = None
        self.csv_file = None
        self.csv = None
        self.frames = 0
        self.size = None
        self.paths = None

    @property
    def active(self):
        """bool: True while a recording is open (video writer exists)."""
        return self.writer is not None

    def start(self, width, height):
        """Open a new MP4 file and CSV file named viewer_<date>_<time> and write the CSV header.

        Args:
            width (int): Video width in pixels. Rounded down to an even number
                because the mp4v codec needs even dimensions.
            height (int): Video height in pixels. Rounded down to an even
                number.

        Raises:
            RuntimeError: If the video writer cannot be opened.
        """
        self.directory.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime("%Y%m%d_%H%M%S")
        self.paths = (self.directory / f"viewer_{stamp}.mp4",
                      self.directory / f"viewer_{stamp}_joints.csv")
        # mp4v wants even dimensions
        self.size = (width & ~1, height & ~1)
        self.writer = cv2.VideoWriter(
            str(self.paths[0]), cv2.VideoWriter_fourcc(*"mp4v"), self.fps, self.size)
        if not self.writer.isOpened():
            self.writer = None
            raise RuntimeError(f"could not open video writer for {self.paths[0]}")
        self.csv_file = open(self.paths[1], "w", newline="")
        self.csv = csv.writer(self.csv_file)
        self.csv.writerow(["video_frame"] + self.columns)
        self.frames = 0

    def write(self, rgb_bottom_up, values):
        """Add one video frame and one CSV row, flushing the CSV file every 30 rows.

        A frame whose size differs from the recording size (the window was
        resized during the recording) is rescaled to the recording size.

        Args:
            rgb_bottom_up (numpy.ndarray): Image of shape (height, width, 3),
                dtype uint8, in red-green-blue (RGB) order with the rows
                bottom-up, as OpenGL returns them.
            values (Sequence[float]): One number per entry of `columns`, in the
                same order. Written with six decimals.
        """
        img = cv2.cvtColor(np.flipud(rgb_bottom_up), cv2.COLOR_RGB2BGR)
        if (img.shape[1], img.shape[0]) != self.size:  # window resized mid-recording
            img = cv2.resize(img, self.size, interpolation=cv2.INTER_AREA)
        self.writer.write(img[:self.size[1], :self.size[0]])
        self.csv.writerow([self.frames] + [f"{v:.6f}" for v in values])
        self.frames += 1
        if self.frames % 30 == 0:
            self.csv_file.flush()

    def stop(self):
        """Close the video and the CSV file.

        Returns:
            tuple | None: (mp4_path, csv_path, frames) with the two
            pathlib.Path objects and the number of video frames written, or
            None if no recording was active.
        """
        if not self.active:
            return None
        self.writer.release()
        self.csv_file.close()
        self.writer = self.csv_file = self.csv = None
        return (*self.paths, self.frames)


def make_glfw_viewer(model, data, vcfg):
    """Open the viewer window and return the viewer as a dictionary of callables.

    Creates the graphics library framework (GLFW) window and an OpenGL
    context, sets up the follow camera (distance 3.5 m, elevation -45
    degrees, vertical field of view (FOV) 90 degrees), and prepares the
    recorder and the panel. Modifies `model`: sets model.vis.global_.fovy and,
    when vcfg["shadowsize"] is set, model.vis.quality.shadowsize. The window
    is titled "Combined Controller". Only the base body "base_link" is
    followed (body id 1 if the model has no such body).

    Args:
        model (mujoco.MjModel): The robot model.
        data (mujoco.MjData): The simulation state that is drawn. Read only.
        vcfg (dict): Viewer settings, all supplied by the launcher. Required
            keys:
              "win": (width, height) of the window in pixels.
              "vsync": int passed to glfw.swap_interval. 0 turns vertical
                synchronisation off, and frame pacing to the loop's tick
                period is then done by the viewer; 1 waits for the display.
              "view_shadows": bool. If false, shadows and reflections are
                switched off in the main view for speed.
              "record_fps": video frames per second of simulated time at the
                loop's tick rate (for example 150). When a recording
                starts it is divided by info["draw_every"].
            Optional keys (read with a default):
              "shadowsize": shadow map size in pixels, or None / 0 to leave
                the model's value.
              "hud": bool, draw the status panel. Defaults to True.
              "insets": bool, draw the camera insets. Defaults to True.
              "record": bool, start recording at frame 0. Defaults to falsy.
              "snapshot_every": seconds between automatic snapshots, 0 for
                none. Defaults to 0.0.
              "snapshot_dir": folder for snapshots. Defaults to the
                "snapshots" folder in the project root.
              "bench_snap_dir": folder; if set, one set of benchmark images
                is written there at the first redraw at or after frame
                "bench_snap_frame" (required when "bench_snap_dir" is set).
              "finish": bool, call mujoco.mjr_finish after each swap.
              "roundrobin": bool, only used to print a note that the camera
                insets take turns when a recording starts.
              "legend_extra": list of (key, label) entries added to the
                key legend. Defaults to an empty list.
              "has_teleop": bool, whether the F2 entry is in the legend.

    Returns:
        dict: The viewer, with these keys:
            "name" (str): "glfw".
            "window": The GLFW window handle.
            "context" (mujoco.MjrContext): The window's rendering context.
                The loop's camera rig renders through it.
            "timers" (dict[str, float]): Seconds accumulated since the viewer
                was created, under "render" (scene render), "hud_insets"
                (panel and insets) and "swap_poll" (buffer swap and event
                polling). Used for the benchmark report.
            "key_down" (Callable[[int], bool]): Takes a GLFW key code and
                returns whether that key is down right now.
            "set_held" (Callable[[Callable[[int], bool]], None]): Takes the
                launcher's held(key_code) function (the real keyboard plus any
                key injection used for testing). The viewer uses it for the
                F3, F4 and F6 keys. Until it is called no key is held.
            "frame" (Callable[[dict], dict]): Called once per tick with an
                info dictionary; see the frame() function inside this
                function for the keys. Returns {"quit": bool, "yaw_deg":
                float}.
            "finish" (Callable[[], None]): Stops an active recording and
                prints where it was saved.
            "close" (Callable[[], None]): glfw.terminate, closes the window.
            "should_close" (Callable[[], bool]): Whether the window has been
                asked to close.

    Raises:
        RuntimeError: If GLFW cannot be initialised or the window cannot be
            created.
    """
    show_hud = vcfg.get("hud", True)
    show_insets = vcfg.get("insets", True)

    # --- Snapshots (press F4 in the MuJoCo window, or --snapshot-every N) ---
    snap_dir = Path(vcfg["snapshot_dir"]) if vcfg.get("snapshot_dir") else PROJECT_ROOT / "snapshots"
    snapshot_every = vcfg.get("snapshot_every", 0.0)
    snap_state = {"last": _time.time(), "p_down": False}
    hud_state = {"last": _time.time(), "ms": 0.0}
    inset_cache = {}
    state = {"held": lambda code: False, "prev_c": False, "prev_r": False, "alert_seq": 0, "yaw_deg": 0.0, "deadline": None, "bench_snapped": False}

    def save_snapshot(rgb, preview_frame):
        """Save the main view, and the operator camera frame if there is one, as PNG files.

        Writes sim_<hhmmss>.png and, when `preview_frame` is not None,
        camera_<hhmmss>.png into the snapshot folder (snap_dir, created if
        needed) and prints their location.

        Args:
            rgb (numpy.ndarray): Main view of shape (height, width, 3), dtype
                uint8, red-green-blue (RGB) order, rows bottom-up as read from
                OpenGL.
            preview_frame (numpy.ndarray | None): Operator webcam frame in
                blue-green-red (BGR) order, as stored by the teleoperation
                source, or None.
        """
        snap_dir.mkdir(parents=True, exist_ok=True)
        stamp = _time.strftime("%H%M%S")
        cv2.imwrite(str(snap_dir / f"sim_{stamp}.png"),
                    cv2.cvtColor(np.flipud(rgb), cv2.COLOR_RGB2BGR))
        pf = preview_frame
        if pf is not None:
            cv2.imwrite(str(snap_dir / f"camera_{stamp}.png"), pf)
        print(f"Snapshot saved: {snap_dir}/sim_{stamp}.png"
              f"{' + camera' if pf is not None else ''}")

    # --- GLFW ---
    glfw.set_error_callback(
        lambda err, desc: print(f"GLFW error {err}: {desc}"))
    if not glfw.init():
        raise RuntimeError("Could not initialise GLFW")
    window = glfw.create_window(*vcfg["win"], "Combined Controller", None, None)
    if not window:
        glfw.terminate()
        raise RuntimeError("GLFW window creation failed")
    glfw.make_context_current(window)
    glfw.swap_interval(vcfg["vsync"])

    model.vis.global_.fovy = FOVY_DEG
    cam = mujoco.MjvCamera()
    opt = mujoco.MjvOption()
    mujoco.mjv_defaultCamera(cam)
    mujoco.mjv_defaultOption(opt)
    setup_follow_camera(cam)

    scene_vis = mujoco.MjvScene(model, maxgeom=10_000)
    if not vcfg["view_shadows"]:
        # The VM GPU renders this scene at ~5 fps with shadows/reflections,
        # too slow to drive or teleoperate the robot.
        scene_vis.flags[mujoco.mjtRndFlag.mjRND_SHADOW] = 0
        scene_vis.flags[mujoco.mjtRndFlag.mjRND_REFLECTION] = 0
    if vcfg.get("shadowsize"):
        model.vis.quality.shadowsize = vcfg["shadowsize"]
    context = mujoco.MjrContext(model, mujoco.mjtFontScale.mjFONTSCALE_150)

    base_body_id = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "base_link")
    if base_body_id < 0:
        base_body_id = 1
    cam_dir = PROJECT_ROOT / CAMERA_SNAPSHOT_DIR
    tm = {"render": 0.0, "hud_insets": 0.0, "swap_poll": 0.0}
    pc = _time.perf_counter

    # Joint columns for the recording: every arm joint and finger, actual
    # position and the PD target, plus the base pose.
    rec_joints = []
    for aid in range(model.nu):
        aname = model.actuator(aid).name
        if "_joint" in aname or "_finger" in aname:
            qa = model.jnt_qposadr[model.actuator_trnid[aid, 0]]
            rec_joints.append((aname.removesuffix("_ctrl"), qa, aid))
    recorder = ViewerRecorder(
        PROJECT_ROOT / "data" / "recordings", vcfg["record_fps"],
        ["sim_time_s", "wall_s", "base_x", "base_y", "base_yaw_deg"]
        + [f"{n}_pos" for n, _, _ in rec_joints]
        + [f"{n}_target" for n, _, _ in rec_joints])
    rec_t0 = [0.0]

    hud_keys = hud_key_list(vcfg.get("has_teleop"), vcfg.get("legend_extra", []))

    # Text is drawn into small RGB bitmaps with OpenCV and blitted with
    # one mjr_drawPixels each. mjr_overlay draws one glyph per GL call,
    # and on this VM's vmwgfx driver every such call leaks a resource id:
    # a ~200 glyph HUD aborted the process at frame ~250 ("Illegal
    # COTable id"). One single-space overlay is kept per frame because the
    # first mjr_drawPixels right after mjr_render is otherwise dropped
    # (eagle inset blank); a few glyphs/frame is far below the limit.
    def blit(img, left, bottom):
        """Draw an image into the window with mjr_drawPixels.

        Args:
            img (numpy.ndarray): Image of shape (height, width, 3), dtype
                uint8, red-green-blue (RGB) order, top row first. It is
                flipped here because OpenGL wants the bottom row first.
            left (int): Distance in pixels from the left window edge to the
                image's left edge.
            bottom (int): Distance in pixels from the bottom window edge to
                the image's bottom edge.
        """
        # drawPixels wants a FLAT contiguous uint8 array, bottom-up rows
        h, w = img.shape[:2]
        flat = np.ascontiguousarray(np.flipud(img)).ravel()
        mujoco.mjr_drawPixels(
            flat, None, mujoco.MjrRect(left, bottom, w, h), context)

    def pace(info):
        """Sleep so that ticks keep to real time when vertical synchronisation is off.

        Does nothing when vcfg["vsync"] is not 0. Otherwise it keeps a
        cumulative schedule (state["deadline"]) with one tick period per call,
        so the fast ticks between redraws pay for the slow redraw ticks. A tick
        that runs late does not sleep, and the schedule is reset if the machine
        falls more than 0.1 s behind (no catching up). Reads and updates
        state["deadline"].

        Args:
            info (dict): The frame info. Uses "tick_dt" (tick period in
                seconds, default 1/60) and "t_frame_start" (time.perf_counter
                value at the start of the tick, used to restart the schedule).
        """
        if vcfg["vsync"] == 0:
            # No vsync pacing: ticks are held to a schedule of one tick period each, so sim time never runs faster than wall
            # time. The schedule is cumulative, so the fast ticks between redraws pay for the slow redraw ticks. A tick that
            # runs late does not sleep; the schedule is reset if the machine falls more than 0.1 s behind (no catching up).
            dt = info.get("tick_dt", 1.0 / 60)
            now = pc()
            if state["deadline"] is None or now - state["deadline"] > 0.1:
                state["deadline"] = info["t_frame_start"] + dt
            else:
                state["deadline"] += dt
            if state["deadline"] > now:
                _time.sleep(state["deadline"] - now)

    def frame(info):
        """Handle one control tick: poll keys, pace, and on redraw ticks draw the viewer.

        On every tick it plays the alert sound once for each new policy request
        and polls the window events (key states are read by the keyboard source
        every tick). On redraw ticks (info["draw"] true) it also:
          * starts or stops a video recording on a rising edge of F6 (or starts
            it at frame 0 when vcfg["record"] is set);
          * saves the full-quality camera images on a rising edge of F3;
          * moves the follow camera to the base and turns it with the base yaw;
          * renders the scene, then draws the banner, the status panel and the
            camera insets;
          * saves a snapshot on a rising edge of F4 or every
            vcfg["snapshot_every"] seconds, and the benchmark images once;
          * writes a frame to the recording if one is active;
          * swaps the buffers.
        Finally it paces the tick. Reads and updates the enclosing scope's
        state, snap_state, hud_state, tm (timers), inset_cache, recorder and
        rec_t0.

        Args:
            info (dict): What the control loop knows this tick. Keys read on
                every tick:
                  "draw" (bool): Redraw this tick. Defaults to True.
                  "alert_seq" (int): Counter of policy requests for the
                    operator. Defaults to 0.
                  "tick_dt" (float): Tick period in seconds, for pacing.
                  "t_frame_start" (float): time.perf_counter value at the
                    start of the tick.
                Keys read on redraw ticks:
                  "frame" (int): Tick number.
                  "time" (float): Simulated time in seconds.
                  "draw_every" (int): Ticks per redraw. Defaults to 1.
                  "images" (dict[str, numpy.ndarray]): Camera name to
                    red-green-blue (RGB) image, top row first, for the insets.
                  "snapshot_images" (Callable[[], dict]): Returns full-quality
                    camera images by name, used by F3 and benchmark snapshots.
                  "base_vel" (tuple[float, float, float]): Base velocity
                    (vx, vy) in metres per second and yaw rate in radians per
                    second, in the world frame.
                  "drive_state" (dict): The keyboard's normalised drive
                    command, with "linear" and "angular" between -1 and 1.
                  "targets" (numpy.ndarray): The loop's position targets,
                    indexed by actuator id (recorded as "_target" columns).
                  "teleop_status" (str | None): Arm control status text, None
                    without teleoperation.
                  "preview_frame" (numpy.ndarray | None): Operator webcam frame
                    in blue-green-red (BGR) order, or None.
                  "preview" (bool): Whether to show the operator camera inset.
                  "status" (str | None): Episode status text for the panel.
                  "mode" (str | None): Controller mode, shown in upper case.
                  "neck_deg" (list[float] | None): Neck joint angles in
                    degrees.
                  "banner" (tuple[str, str] | None): (text, kind) for the bar
                    along the top: kind "needed" draws a red bar, any other kind
                    a blue bar.

        Returns:
            dict: {"quit": bool, "yaw_deg": float}. "quit" is True once the
            window has been asked to close. "yaw_deg" is the base yaw in
            degrees as of the last redraw (the follow camera's heading).
        """
        held = state["held"]
        t = info["time"]
        fr = info["frame"]
        if info.get("alert_seq", 0) != state["alert_seq"]:      # a policy request for the operator: sound once (the banner shows on the redraws)
            state["alert_seq"] = info.get("alert_seq", 0)
            play_alert()
        if not info.get("draw", True):
            # Between redraws: key states still update every tick (the keyboard source reads them), and the tick is paced.
            t_s0 = pc()
            glfw.poll_events()
            tm["swap_poll"] += pc() - t_s0
            pace(info)
            return {"quit": bool(glfw.window_should_close(window)), "yaw_deg": state["yaw_deg"]}
        images = info["images"]
        hold_qpos_targets = info["targets"]
        base_vx, base_vy, base_wz = info["base_vel"]
        t_f0 = info["t_frame_start"]

        cur_r = held(glfw.KEY_F6)
        if (cur_r and not state["prev_r"]) or (vcfg.get("record") and fr == 0):  # --record starts on frame 0
            if recorder.active:
                mp4, csv_path, n = recorder.stop()
                print(f"Recording stopped: {n} frames ({n / recorder.fps:.1f} s sim time)\n"
                      f"  video:  {mp4}\n  joints: {csv_path}")
            else:
                fb_w, fb_h = glfw.get_framebuffer_size(window)
                recorder.fps = vcfg["record_fps"] / info.get("draw_every", 1)     # one video frame per redraw
                recorder.start(fb_w, fb_h)
                rec_t0[0] = _time.time()
                print(f"Recording started: {recorder.paths[0]}  ({recorder.fps:g} fps sim time)")
                if vcfg.get("roundrobin"):
                    print("  note: cameras take turns (each updates at CAMERA_HZ/3); "
                          "run with CC_ROUNDROBIN=0 for full-rate camera insets in the video")
        state["prev_r"] = cur_r

        cur_c = held(glfw.KEY_F3)
        if cur_c and not state["prev_c"]:
            cam_dir.mkdir(parents=True, exist_ok=True)
            stamp = _time.strftime("%H%M%S")
            for cname, img in info["snapshot_images"]().items():      # full-quality (policy) frames, not the operator insets
                cv2.imwrite(str(cam_dir / f"{cname}_{stamp}.png"),
                            cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
            print(f"Camera images saved: {cam_dir}/*_{stamp}.png")
        state["prev_c"] = cur_c

        # Camera follow
        yaw_deg = update_follow_camera(cam, data, base_body_id)
        state["yaw_deg"] = yaw_deg

        # Render
        width, height = glfw.get_framebuffer_size(window)
        viewport = mujoco.MjrRect(0, 0, width, height)
        t_r0 = pc()
        mujoco.mjv_updateScene(
            model, data, opt, None, cam,
            mujoco.mjtCatBit.mjCAT_ALL, scene_vis)
        mujoco.mjr_render(viewport, scene_vis, context)
        t_r1 = pc()
        tm["render"] += t_r1 - t_r0

        if show_hud or show_insets:
            mujoco.mjr_overlay(
                mujoco.mjtFont.mjFONT_NORMAL,
                mujoco.mjtGridPos.mjGRID_TOPLEFT, viewport, " ", None, context)
        banner_h = 0
        if info.get("banner"):
            # A full-width bar along the top: red for a request nobody has answered, blue while the operator has control.
            bar = banner_bitmap(*info["banner"], width)
            banner_h = bar.shape[0]
            blit(bar, 0, height - banner_h)
        if show_hud:
            now = _time.time()
            dt_wall = now - hud_state["last"]
            hud_state["last"] = now
            # Smooth frame TIME, not fps: averaging 1/dt is dominated by the
            # fast frames between camera ticks and overstates the rate.
            hud_state["ms"] += 0.1 * (1000.0 * dt_wall - hud_state["ms"])
            ds = info["drive_state"]
            teleop_status = info.get("teleop_status")
            hud = hud_bitmap(hud_rows(
                t, (base_vx, base_vy, base_wz), yaw_deg, data.qpos[0:3],
                middle_rows=[
                    ("frame (ms, fps)", f"{hud_state['ms']:.0f}, "
                     f"{1000.0 / max(hud_state['ms'], 1e-6):.1f}"),
                    ("cmd lin, ang", f"{ds.get('linear', 0):+.2f}, "
                     f"{ds.get('angular', 0):+.2f}"),
                    ("recording (F6)", "off" if not recorder.active else
                     f"REC {recorder.frames} frames, {recorder.frames / recorder.fps:.1f} s")],
                status=info.get("status"), mode=info.get("mode"), neck_deg=info.get("neck_deg"),
                extra_rows=([("arms (F2 toggles)", teleop_status)] if teleop_status is not None else [])), hud_keys)
            hud_left, hud_top = hud_position(1.0, banner_h)
            blit(hud, hud_left, height - hud.shape[0] - hud_top)
        if show_insets:
            # One row of insets along the bottom: the simulated cameras, plus
            # the operator webcam in teleop runs. Each is scaled to fit the
            # window width (at most half size), with its name burned into the
            # top-left corner. Images are top-down; blit flips them.
            tiles = list(images.items())
            if info.get("teleop_status") is not None and info.get("preview"):
                pf = info.get("preview_frame")
                tiles.append(("operator_cam", None if pf is None else
                              cv2.cvtColor(pf, cv2.COLOR_BGR2RGB)))
            iw, ih, gap, xs = inset_layout(width, len(tiles))
            for (cname, img), x in zip(tiles, xs):
                # The simulated cameras only change on their render ticks, so
                # keep the scaled, labelled tile until the source array does.
                cached = inset_cache.get(cname)
                if img is not None and cached is not None \
                        and cached[0] is img and cached[1].shape[1] == iw:
                    small = cached[1]
                else:
                    small = inset_tile(cname, img, iw, ih)
                    inset_cache[cname] = (img, small)
                blit(small, x, gap)
        tm["hud_insets"] += pc() - t_r1
        p_now = held(glfw.KEY_F4)
        due = snapshot_every > 0 and \
            _time.time() - snap_state["last"] >= snapshot_every
        if (p_now and not snap_state["p_down"]) or due:
            snap_state["last"] = _time.time()
            rgb = np.zeros((height, width, 3), dtype=np.uint8)
            mujoco.mjr_readPixels(rgb, None, viewport, context)
            save_snapshot(rgb, info.get("preview_frame"))
        snap_state["p_down"] = p_now
        if vcfg.get("bench_snap_dir") and fr >= vcfg["bench_snap_frame"] and not state["bench_snapped"]:   # the first redraw at or after the frame
            state["bench_snapped"] = True
            sd = Path(vcfg["bench_snap_dir"]); sd.mkdir(parents=True, exist_ok=True)
            rgb = np.zeros((height, width, 3), dtype=np.uint8)
            mujoco.mjr_readPixels(rgb, None, viewport, context)
            cv2.imwrite(str(sd / "main.png"),
                        cv2.cvtColor(np.flipud(rgb), cv2.COLOR_RGB2BGR))
            for cname, img in info["snapshot_images"]().items():
                cv2.imwrite(str(sd / f"{cname}.png"),
                            cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
        if recorder.active:
            rgb = np.zeros((height, width, 3), dtype=np.uint8)
            mujoco.mjr_readPixels(rgb, None, viewport, context)
            recorder.write(rgb, [
                data.time, _time.time() - rec_t0[0],
                data.qpos[0], data.qpos[1], yaw_deg]
                + [data.qpos[qa] for _, qa, _ in rec_joints]
                + [hold_qpos_targets[aid] for _, _, aid in rec_joints])
        t_s0 = pc()
        glfw.swap_buffers(window)
        glfw.poll_events()
        if vcfg.get("finish"):
            mujoco.mjr_finish()
        tm["swap_poll"] += pc() - t_s0

        pace(info)
        return {"quit": bool(glfw.window_should_close(window)), "yaw_deg": yaw_deg}

    def finish():
        """Stop an active recording and print the number of frames and the file paths."""
        if recorder.active:
            mp4, csv_path, n = recorder.stop()
            print(f"Recording stopped: {n} frames ({n / recorder.fps:.1f} s sim time)\n"
                  f"  video:  {mp4}\n  joints: {csv_path}")

    return {
        "name": "glfw", "window": window, "context": context, "timers": tm,
        "key_down": lambda code: glfw.get_key(window, code) == glfw.PRESS,
        "set_held": lambda fn: state.__setitem__("held", fn),
        "frame": frame, "finish": finish, "close": glfw.terminate,
        "should_close": lambda: glfw.window_should_close(window),
    }
